/* 西班牙语词库 · 给「英语母语、学西班牙语」那一档用的（2026-09-23 加，见 CLAUDE.md「多语言与新手教程」那一节）
   ⚠️ 这个文件是 es-words/build.py 生成的 —— **别手改**，改 es-words/g1~g5.txt 然后重跑脚本。
   分档跟英语词库一模一样：1~5 = A1 / A2 / B1 / B2 / B2–C1（五章：石廊 A1 … 墟心 B2，无尽 B1+B2+C1 混出）。
   英文释义是**逐条手写的最常用义**；名词带冠词（el / la / el/la / los / las），题面上显示。

   格式：[西语, 英文释义, 类别, 难度, 词性, 冠词]   冠词只有名词才有，其余是 ""
   ⚠️ 跟别的词库一样**共用同一套全局变量**：学西班牙语时下面那段把 WORDS / WMAP / BYCAT / BYPOS / BYLV / ALLW
      整套换成这一份。词对象的 en 是「要学的那个词」（这里是西语），cn 是母语释义（这里是英文），多一个 ar（冠词）。
   ⚠️ **只许往数组末尾追加**（存档码按下标存熟练度）。西语不许重复，同一难度里英文释义不许重复，最长 11 个字母。
   ⚠️ 跟英语拼写一样的词（pan / pie / once / red…）是允许的：熟练度表 LEX 里西语存成 "es:词"（game.js 的 lexKey()），不会串。*/
